import fs from 'node:fs';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
const root='preview/';
const rc5=fs.readFileSync(root+'PHALANX_RC5_ALPHA_DERIVED_20261017.html','utf8');
const v2=fs.readFileSync(root+'PHALANX_RC5_OUT024_ISOLATED_NAV_TEST_V2_20261018.html','utf8');
const map=fs.readFileSync(root+'PHX-OUT-024-MAP2-FROZEN-20261018.html');
const lock=JSON.parse(fs.readFileSync('data/outpost-map-alpha24-canonical-lock-20261018.json','utf8'));
assert.equal(crypto.createHash('sha256').update(map).digest('hex'),lock.original.sha256,'OUT-024 source changed');
assert.equal(map.length,lock.original.bytes,'OUT-024 size changed');
assert.equal((rc5.match(/<a\b[^>]*href=["'][^"']+["']/g)||[]).length,39,'RC5 anchor count changed; review routing');
assert.equal((rc5.match(/<a\b[^>]*data-pending=["']true["'][^>]*>/g)||[]).length,32,'RC5 pending anchor count changed');
assert.equal((rc5.match(/Outpost Map<small class="status unlinked">NOT LINKED/g)||[]).length,1,'Outpost Map menu changed');
assert.match(v2,/src="\.\/PHALANX_RC5_ALPHA_DERIVED_20261017\.html"/);
assert.match(v2,/const out='\.\/PHX-OUT-024-MAP2-FROZEN-20261018\.html'/);
assert.match(v2,/back\.addEventListener\('click',showRc5\)/);
assert.match(v2,/matches\.length!==1/);
assert.match(v2,/event\.stopImmediatePropagation\(\)/);
assert.match(v2,/anchor\.addEventListener\('click',[\s\S]*?\},true\)/);
assert.match(v2,/frame\.addEventListener\('load'/);
console.log('PASS: RC5 original, 32 pending anchors, OUT-024 SHA256 and V2 isolated navigation contract');
console.log('NOTE: static checks only; browser, deployment and Android behavior unverified');
